#include "ksPanelByteTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
#include <utility>
int main(){using T=ks::PanelByteTask;using S=T::Stage;using P=T::Port;unsigned cases=0;for(unsigned kind=0;kind<4;++kind)for(unsigned input=0;input<256;++input)for(unsigned data=0;data<256;++data){T t(static_cast<T::Kind>(kind));unsigned used=0,reads=0;std::vector<std::pair<P,unsigned>>writes;auto clock=[](P){return 1u;};while(t.stage()!=S::Complete){auto cost=t.nextClocks(clock);if(t.advanceBefore(cost-1,[](T::Read){return 0;},[](P,uint8_t){},clock))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r){++reads;if((r==T::Read::Data)!=t.reading())throw std::runtime_error("read kind");return t.reading()?data:input;},[&](P p,uint8_t v){writes.emplace_back(p,v);},clock);}unsigned base=kind==0?0x30:kind==1?0x32:kind==2?0x31:0x33;std::vector<std::pair<P,unsigned>>expected;if(t.reading())expected.emplace_back(P::Gate,0);expected.emplace_back(P::Control,base);expected.emplace_back(P::Control,base+8);if(!t.reading())expected.emplace_back(P::Data,input);expected.emplace_back(P::Control,base);if(t.reading())expected.emplace_back(P::Gate,255);if(writes!=expected||reads!=1||t.data()!=(t.reading()?data:input)||used!=(t.reading()?96u:76u))throw std::runtime_error("sequence/result/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure panel-byte properties\n";}
